-- PT118-S3-Q16. Batch 05.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT118-S3-Q16$batch05$ AND q.stimulus=$batch05$Numerous paintings and engravings representing warfare can be found in remains of all civilizations going back to and including the Neolithic period, when agriculture was first developed. However, no paintings or engravings of warfare are found dating from before the Neolithic period. Therefore, warfare must have first developed as a result of the transition to an agricultural society.$batch05$ AND q.prompt=$batch05$Which one of the following is an assumption required by the argument?$batch05$ AND q.correct_choice=$batch05$C$batch05$) THEN RAISE EXCEPTION 'Question changed: PT118-S3-Q16'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch05$PT118-S3-Q16$batch05$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT118-S3-Q16'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT118-S3-Q16$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$Warfare first developed as a result of the move to agriculture.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$Paintings and engravings of warfare appear in every civilization from the Neolithic period on, when agriculture began. None appear before it.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$The author jumps from "no *pictures* of war" to "no *war*." Those are different things. People could have fought for thousands of years without painting it. When an argument treats the absence of a record as the absence of the thing, the answer defends that leap.$batch05$), (3, $batch05$Goal$batch05$, $batch05$A defender: there was no warfare before people started painting and engraving it.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT118-S3-Q16$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$Whether painting was the dominant art form says nothing about whether war existed before it.$batch05$), ($batch05$B$batch05$, $batch05$The argument says agriculture led to warfare. It does not need every Neolithic war to be about farmland.$batch05$), ($batch05$C$batch05$, $batch05$Negate it: "there *was* warfare before the first war paintings." Then the lack of earlier pictures proves nothing, and warfare could predate agriculture.$batch05$), ($batch05$D$batch05$, $batch05$"Inevitable result of civilization" is a much bigger claim than the author makes or needs.$batch05$), ($batch05$E$batch05$, $batch05$This is the most popular wrong answer, and it is tempting because it seems to tie farming and war together in the art. But the argument does not care when people started painting farms. Negate it: "paintings of farm life began at a different time than paintings of war." The argument is untouched, because it rests on when war paintings appear, not farm paintings.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT118-S3-Q16$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
